<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { MdButton, MdSwitch, describeError } from '@nyabula/ui';
import { useSessionStore } from '../../../stores/session';
import { useVisiblePoll } from '../../../composables/usePageVisible';
import CrossoverControls from './CrossoverControls.vue';
import { LEGACY_BANDS, LISTENING_PRESETS, expandLegacyBands, presetMasterDb, eqPreset, eqResponse, eqPeak, validBands, type EqBand } from '../../../lib/dspEqualizer';
const props=defineProps<{mode:'eq'|'subwoofer'}>();
interface Config { eqEnabled:boolean;masterDb:number;crossoverHz:number;satelliteHighpassHz?:number;bassLowpassHz?:number;bassEnabled:boolean;bypass:boolean;eqDb:number[];eqBands:EqBand[];eqBands16?:EqBand[];outputGainDb:number[];delayMs:number[];invert:boolean[] }
interface Status { settingsSaved?:boolean;config:Config;running:boolean;stopping:boolean;source?:string;track:string;sampleRate:number;processedFrames:number;outputPeak:number;usbClockPpm:number;usbUnderruns:number;lastError:number;bassPresent:boolean;satelliteDevice:string;bassDevice:string;simulated?:boolean }
type CustomPreset={name:string;config:Pick<Config,'eqBands16'|'masterDb'|'eqEnabled'>};
const customPresets=ref<CustomPreset[]>([]),presetName=ref(''),selectedPreset=ref('');
const nameValid=computed(()=>!!presetName.value.trim()&&new TextEncoder().encode(presetName.value.trim()).length<=48&&!/[\x00-\x1f\x7f]/.test(presetName.value));
const existingPreset=computed(()=>customPresets.value.some(p=>p.name===presetName.value.trim()));
const liveEnabled=ref(true),liveBusy=ref(false);let previewTimer:ReturnType<typeof setTimeout>|undefined;let lastPreview='';let disposed=false;
const session=useSessionStore(); const status=ref<Status>(); const draft=ref<Config>();
const independentCrossover=ref(false);
const error=ref(''),busy=ref(false),dirty=ref(false),track=ref(''),tracks=ref<string[]>([]),active=ref(0),dragging=ref<number>();let refreshing=false;
const channels=['左声道','右声道','低音炮'];
const colors=Array.from({length:16},(_,i)=>`hsl(${35+i*20} 62% 68%)`);
const presetBands=Object.fromEntries(LISTENING_PRESETS.map(p=>[p.id,eqPreset(p.id)]));
const ticks=[20,50,100,200,500,1000,2000,5000,10000,20000];
const types=[{value:'peak',label:'钟形 · Peak'},{value:'lowShelf',label:'低架 · Low shelf'},{value:'highShelf',label:'高架 · High shelf'}];
const canEdit=computed(()=>session.canControl&&session.connected&&!!draft.value&&!busy.value);
const valid=computed(()=>!!draft.value&&validBands(draft.value.eqBands)&&Number.isFinite(draft.value.masterDb)&&draft.value.masterDb>=-30&&draft.value.masterDb<=0);
const band=computed(()=>draft.value?.eqBands[active.value]);
const boost=computed(()=>valid.value&&draft.value!.eqEnabled?eqPeak(draft.value!.eqBands):0);
const requiredMaster=computed(()=>-Math.ceil(boost.value+Math.max(0,...(draft.value?.outputGainDb.slice(0,draft.value.bassEnabled?3:2)??[]))+1));
const recommended=computed(()=>Math.max(-30,requiredMaster.value));
const headroomInsufficient=computed(()=>requiredMaster.value < -30);
const headroomLow=computed(()=>!!draft.value&&!draft.value.bypass&&draft.value.masterDb>requiredMaster.value);
const sourceLabel=computed(()=>(({bluetooth:'蓝牙音乐',tts:'语音播报',file:'文件播放',test:'测试文件'} as Record<string,string>)[status.value?.source??'']??'音频输出'));
const logFrequency=computed({get:()=>Math.log10(band.value?.frequencyHz??1000),set:(v:number)=>{if(band.value){band.value.frequencyHz=Math.round(10**v);dirty.value=true;}}});
function hz(value:number){if(!Number.isFinite(value))return '—';return value>=1000?`${+(value/1000).toFixed(2)}k`:`${+value.toFixed(1)}`;}
function db(value:number){return Number.isFinite(value)?`${value>0?'+':''}${value.toFixed(1)}`:'—';}
function x(f:number){return 46+Math.log10(f/20)/3*686;}
function y(g:number){return 126-g*7;}
function curve(bands:EqBand[]){if(!validBands(bands))return '';return Array.from({length:321},(_,i)=>{const f=20*1000**(i/320);return `${i?'L':'M'}${x(f).toFixed(2)},${Math.max(14,Math.min(238,y(eqResponse(bands,f)))).toFixed(2)}`;}).join(' ');}
const responsePath=computed(()=>draft.value?curve(draft.value.eqBands):'');
const savedPath=computed(()=>status.value?curve(status.value.config.eqBands):'');
function normalize(config:Config):Config {const c=JSON.parse(JSON.stringify(config));c.satelliteHighpassHz??=c.crossoverHz;c.bassLowpassHz??=c.crossoverHz;c.eqEnabled=c.eqEnabled!==false;c.eqBands=expandLegacyBands(c.eqBands16??c.eqBands,c.eqDb).map(b=>({...b,frequencyHz:Math.round(b.frequencyHz*100)/100,q:Math.round(b.q*1000)/1000,gainDb:Math.round(b.gainDb*100)/100}));return c;}
function accept(value:unknown){const s=value as Status;if(!s?.config||!Array.isArray(s.config.eqDb))throw Error('DSP 状态格式无效');independentCrossover.value=Number.isFinite(s.config.satelliteHighpassHz)&&Number.isFinite(s.config.bassLowpassHz);s.config=normalize(s.config);status.value=s;if(!dirty.value)draft.value=normalize(s.config);}
async function refresh(){if(!session.connected||refreshing||busy.value||liveBusy.value)return;refreshing=true;try{accept(await session.request('dsp.status'));error.value='';}catch(e){error.value=describeError(e);}finally{refreshing=false;}}
async function library(){try{const r=await session.request('music.library');tracks.value=((r.items??[]) as any[]).filter(t=>t.supported&&t.sampleRate===48000&&t.channels===2&&t.bits===16).map(t=>t.name);if(!tracks.value.includes(track.value))track.value=tracks.value[0]??'';}catch(e){error.value=describeError(e);}}
async function action(topic:string,data:Record<string,unknown>={}){busy.value=true;error.value='';try{const r=await session.request(topic,data);if(topic==='dsp.config')dirty.value=false;accept(r);return true;}catch(e){error.value=describeError(e);return false;}finally{busy.value=false;}}
function payload(){const c={...draft.value!};if(independentCrossover.value)c.crossoverHz=c.satelliteHighpassHz??c.crossoverHz;else{delete c.satelliteHighpassHz;delete c.bassLowpassHz;}return {...c,eqBands16:c.eqBands,eqBands:LEGACY_BANDS.map(i=>c.eqBands[i]),eqDb:LEGACY_BANDS.map(i=>c.eqBands[i]!.gainDb)};}
function cancelPreview(){if(previewTimer){clearTimeout(previewTimer);previewTimer=undefined;}}
async function preview(){previewTimer=undefined;if(disposed||!liveEnabled.value||!dirty.value||!valid.value||!canEdit.value)return;if(liveBusy.value){queuePreview();return;}const data=JSON.parse(JSON.stringify(payload()));const key=JSON.stringify(data);if(key===lastPreview)return;liveBusy.value=true;try{accept(await session.request('dsp.config',{...data,persist:false}));lastPreview=key;error.value='';}catch(e){error.value=describeError(e);}finally{liveBusy.value=false;}}
function queuePreview(){if(props.mode==='eq'&&liveEnabled.value&&dirty.value&&valid.value&&!previewTimer&&!disposed)previewTimer=setTimeout(()=>void preview(),160);}
async function apply(){if(draft.value&&valid.value&&!liveBusy.value){cancelPreview();lastPreview='';return await action('dsp.config',payload());}return false;}
watch(draft,queuePreview,{deep:true});
watch(liveEnabled,(v)=>{if(v)queuePreview();else cancelPreview();});
onBeforeUnmount(()=>{disposed=true;cancelPreview();});
async function listenPreset(id:string){if(!canEdit.value||liveBusy.value||!draft.value)return;const bands=eqPreset(id);draft.value.eqBands=bands;draft.value.masterDb=presetMasterDb(bands);draft.value.bypass=false;draft.value.eqEnabled=true;dirty.value=true;await apply();}
function presetSelected(id:string){const c=status.value?.config;const b=presetBands[id];return !!c&&!!b&&c.eqEnabled&&!c.bypass&&Math.abs(c.masterDb-presetMasterDb(b))<.01&&c.eqBands.every((v,i)=>v.enabled&&v.type===b[i]!.type&&Math.abs(v.frequencyHz-b[i]!.frequencyHz)<.01&&Math.abs(v.gainDb-b[i]!.gainDb)<.001&&Math.abs(v.q-b[i]!.q)<.001);}
function presetThumbnail(id:string){return Array.from({length:81},(_,i)=>`${i?'L':'M'}${i},${(21-eqResponse(eqPreset(id),31.5*(16000/31.5)**(i/80))*2).toFixed(2)}`).join(' ');}
function undo(){if(status.value&&!liveBusy.value){cancelPreview();lastPreview='';void action('dsp.config',{restore:true});}}
async function loadPresets(){try{const r=await session.request('dsp.presets');customPresets.value=(r.items??[]) as CustomPreset[];}catch(e){error.value=describeError(e);}}
async function savePreset(){if(!canEdit.value||liveBusy.value||!nameValid.value)return;if(!(await apply()))return;busy.value=true;try{const name=presetName.value.trim();const r=await session.request('dsp.preset.save',{name,overwrite:existingPreset.value});customPresets.value=(r.items??[]) as CustomPreset[];selectedPreset.value=name;presetName.value='';error.value='';}catch(e){error.value=describeError(e);}finally{busy.value=false;}}
async function loadPreset(){const p=customPresets.value.find(p=>p.name===selectedPreset.value);if(!p||!draft.value||!canEdit.value||liveBusy.value)return;draft.value.eqBands=JSON.parse(JSON.stringify(p.config.eqBands16));draft.value.masterDb=p.config.masterDb;draft.value.eqEnabled=p.config.eqEnabled!==false;dirty.value=true;await apply();}
async function deletePreset(){if(!selectedPreset.value||!canEdit.value||liveBusy.value||!window.confirm(`删除预设“${selectedPreset.value}”？当前调音不会改变。`))return;busy.value=true;try{const r=await session.request('dsp.preset.delete',{name:selectedPreset.value});customPresets.value=(r.items??[]) as CustomPreset[];selectedPreset.value='';error.value='';}catch(e){error.value=describeError(e);}finally{busy.value=false;}}
function resetEq(){if(!canEdit.value||liveBusy.value||!draft.value)return;draft.value.eqBands=eqPreset('flat');draft.value.eqEnabled=true;dirty.value=true;void apply();}
async function toggleBass(){
  if(!draft.value||liveBusy.value)return;
  const enabled=draft.value.bassEnabled;
  const previous=status.value?.config.bassEnabled??!enabled;
  const wasDirty=dirty.value;
  cancelPreview();liveBusy.value=true;error.value='';
  try{
    // Toggle only the mode; preserve unsaved calibration edits in the panel.
    dirty.value=true;
    accept(await session.request('dsp.config',{bassEnabled:enabled,persist:false}));
    dirty.value=wasDirty;
  }catch(e){draft.value.bassEnabled=previous;error.value=describeError(e);dirty.value=wasDirty;}
  finally{liveBusy.value=false;}
}
function toggleEq(){dirty.value=true;void apply();}
function pointDown(e:PointerEvent,index:number){active.value=index;if(!canEdit.value)return;dragging.value=index;(e.currentTarget as Element).setPointerCapture(e.pointerId);e.preventDefault();}
function pointMove(e:PointerEvent){if(dragging.value===undefined||!draft.value)return;const svg=(e.currentTarget as Element).closest('svg')!;const rect=svg.getBoundingClientRect();const px=(e.clientX-rect.left)*760/rect.width,py=(e.clientY-rect.top)*264/rect.height;const b=draft.value.eqBands[dragging.value]!;b.frequencyHz=Math.round(Math.max(20,Math.min(18000,20*1000**((px-46)/686))));b.gainDb=Math.max(-12,Math.min(12,Math.round((126-py)/7*(b.type==='peak'?1:2)*2)/2));dirty.value=true;}
function pointKey(e:KeyboardEvent,index:number){if(!canEdit.value||!draft.value)return;const b=draft.value.eqBands[index]!;if(e.key==='ArrowUp'||e.key==='ArrowDown')b.gainDb=Math.max(-12,Math.min(12,b.gainDb+(e.key==='ArrowUp'?.5:-.5)));else if(e.key==='ArrowLeft'||e.key==='ArrowRight')b.frequencyHz=Math.round(Math.max(20,Math.min(18000,b.frequencyHz*(e.key==='ArrowRight'?1.05:1/1.05))));else return;active.value=index;dirty.value=true;e.preventDefault();}
watch(()=>session.client,()=>{status.value=undefined;draft.value=undefined;dirty.value=false;customPresets.value=[];selectedPreset.value='';void refresh();void library();void loadPresets();},{immediate:true});
useVisiblePoll(()=>void refresh(),2000);
</script>
<template>
  <div class="dsp-control">
    <div v-if="error" class="service-error" role="alert"><strong>{{status?'操作未完成':'当前设备未提供 DSP 服务'}}</strong><span>{{error}}</span><MdButton variant="text" @click="refresh">重试</MdButton></div>
    <p v-if="status?.simulated" class="service-note">模拟器仅预览设置，没有真实音频输出。</p>
    <template v-if="draft && status">
      <section class="ui-panel control-card">
        <div class="section-head"><div><span class="eyebrow">{{mode==='eq'?'PARAMETRIC EQ':'OUTPUT CALIBRATION'}}</span><h3>{{mode==='eq'?'16 段，细调你的声音':'低音炮与声道校准'}}</h3><p>{{mode==='eq'?'蓝牙音乐、语音播报、文件播放共用；通话保持独立。':'未连接低音炮时保持关闭，左右声道继续输出全频。'}}</p></div><span class="mode-tag">{{draft.bassEnabled?'2.1 分频':'全频立体声'}}</span></div>
        <template v-if="mode==='eq'">
          <div class="listening-presets"><button v-for="p in LISTENING_PRESETS" :key="p.id" :disabled="!canEdit||liveBusy" :class="{chosen:presetSelected(p.id)&&!dirty}" @click="listenPreset(p.id)"><svg viewBox="0 0 80 40" aria-hidden="true"><path :d="`${presetThumbnail(p.id)} L80,40 L0,40Z`"/></svg><strong>{{p.name}}</strong><small>{{p.detail}}</small></button></div>
          <p class="hint">预设包含主增益补偿，点击即应用。手动调节后，满意再保存。</p>
          <section class="custom-presets" aria-label="自定义预设">
            <strong>我的预设</strong>
            <div class="preset-row"><select v-model="selectedPreset" aria-label="自定义预设" :disabled="!canEdit||liveBusy||!customPresets.length"><option value="" disabled>{{customPresets.length?'选择已保存的声音':'还没有自定义预设'}}</option><option v-for="p in customPresets" :key="p.name" :value="p.name">{{p.name}}</option></select><MdButton variant="tonal" :disabled="!selectedPreset||!canEdit||liveBusy" @click="loadPreset">应用预设</MdButton><MdButton variant="text" :disabled="!selectedPreset||!canEdit||liveBusy" @click="deletePreset">删除</MdButton></div>
            <div class="preset-row"><input v-model="presetName" type="text" aria-label="预设名称" placeholder="为当前调音命名" maxlength="48" :disabled="!canEdit||liveBusy" @keydown.enter.prevent="savePreset"/><MdButton variant="tonal" :disabled="!canEdit||liveBusy||!valid||!nameValid||(!existingPreset&&customPresets.length>=8)" @click="savePreset">{{existingPreset?'覆盖同名预设':'保存为预设'}}</MdButton></div>
            <p class="hint">保留 16 段参数与主增益，刷新、重启后仍可使用。{{customPresets.length}} / 8</p>
          </section>
          <div class="setting"><div><strong>启用均衡器</strong><p>关闭后保留调音参数，主增益和声道校准不变。</p></div><MdSwitch v-model="draft.eqEnabled" aria-label="启用均衡器" :disabled="!canEdit||liveBusy||!valid" @update:model-value="toggleEq"/></div>
          <div class="setting"><div><strong>实时生效</strong><p>修改立即试听；保存后重启保留，撤销回到上次保存的声音。</p></div><MdSwitch v-model="liveEnabled" aria-label="实时生效" :disabled="!canEdit"/></div>
          <div class="curve-wrap">
            <div class="curve-label"><span>EQ 频响 <small>不含主增益、分频和限幅</small></span><span :class="{unsaved:dirty}">{{liveBusy?'正在实时更新':!draft.eqEnabled?'均衡器已关闭':draft.bypass?'当前旁通 · 曲线未生效':dirty&&!liveEnabled?'预览 · 尚未应用':status.settingsSaved===false?'实时生效 · 未保存':'已应用'}}</span></div>
            <svg viewBox="0 0 760 264" class="response-graph" role="group" aria-label="均衡器频率响应，可拖动频段控制点">
              <defs><linearGradient id="eq-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--md-primary)" stop-opacity=".17"/><stop offset="100%" stop-color="var(--md-primary)" stop-opacity=".01"/></linearGradient><clipPath id="eq-clip"><rect x="46" y="14" width="686" height="224"/></clipPath></defs>
              <g class="grid"><line v-for="f in ticks" :key="f" :x1="x(f)" :x2="x(f)" y1="14" y2="238"/><line v-for="g in [-12,-6,0,6,12]" :key="g" x1="46" x2="732" :y1="y(g)" :y2="y(g)" :class="{zero:g===0}"/></g>
              <g class="axis"><text v-for="g in [-12,-6,0,6,12]" :key="g" x="36" :y="y(g)+4" text-anchor="end">{{g>0?'+':''}}{{g}}</text><text v-for="f in [20,100,1000,10000,20000]" :key="f" :x="x(f)" y="258" text-anchor="middle">{{hz(f)}}</text></g>
              <g clip-path="url(#eq-clip)"><path :d="`${responsePath} L732,238 L46,238 Z`" fill="url(#eq-fill)"/><path v-if="dirty" :d="savedPath" class="saved-curve"/><path :d="responsePath" class="main-curve" :class="{bypassed:draft.bypass||!draft.eqEnabled}"/></g>
              <g v-for="(b,i) in draft.eqBands" :key="i" class="point" :class="{selected:active===i,off:!b.enabled}" :transform="`translate(${x(b.frequencyHz)},${y(b.type==='peak'?b.gainDb:b.gainDb/2)})`" role="button" tabindex="0" :aria-label="`频段 ${i+1}，${b.frequencyHz} Hz，${db(b.gainDb)} dB；方向键调整`" @focus="active=i" @pointerdown="pointDown($event,i)" @pointermove="pointMove" @pointerup="dragging=undefined" @pointercancel="dragging=undefined" @lostpointercapture="dragging=undefined" @keydown="pointKey($event,i)"><circle r="20" fill="transparent"/><circle r="11" :fill="colors[i]"/><text y="4" text-anchor="middle">{{i+1}}</text></g>
            </svg>
            <p class="graph-tip">拖动圆点调频率与增益，或用下方数值精调。虚线为设备当前应用的曲线。</p>
          </div>
          <div class="band-tabs" role="tablist" aria-label="选择频段"><button v-for="(b,i) in draft.eqBands" :key="i" role="tab" :aria-selected="active===i" :class="{active:active===i,disabled:!b.enabled}" :style="{'--band-color':colors[i]}" @click="active=i"><span class="band-dot">{{i+1}}</span><span><strong>{{hz(b.frequencyHz)}} Hz</strong><small>{{b.enabled?`${db(b.gainDb)} dB`:'已关闭'}}</small></span></button></div>
          <div v-if="band" class="band-editor" role="tabpanel" :aria-label="`频段 ${active+1} 设置`">
            <div class="editor-head"><label>滤波器类型<select v-model="band.type" :disabled="!canEdit" @change="dirty=true"><option v-for="t in types" :key="t.value" :value="t.value">{{t.label}}</option></select></label><MdSwitch v-model="band.enabled" label="启用此段" :disabled="!canEdit" @update:model-value="dirty=true"/></div>
            <div class="knobs"><label><span>频率 <small>Hz</small></span><input v-model.number="band.frequencyHz" type="number" min="20" max="18000" step="1" aria-label="频段频率 Hz" :disabled="!canEdit" @input="dirty=true"/><input v-model.number="logFrequency" type="range" :min="Math.log10(20)" :max="Math.log10(18000)" step="0.002" aria-label="对数频率" :disabled="!canEdit"/></label><label><span>增益 <small>dB</small></span><input v-model.number="band.gainDb" type="number" min="-12" max="12" step="0.5" aria-label="频段增益 dB" :disabled="!canEdit" @input="dirty=true"/><input v-model.number="band.gainDb" type="range" min="-12" max="12" step="0.5" aria-label="增益滑块" :disabled="!canEdit" @input="dirty=true"/></label><label><span>Q <small>{{band.type==='peak'?'带宽':'过渡共振'}}</small></span><input v-model.number="band.q" type="number" min="0.2" max="10" step="0.05" aria-label="频段 Q 值" :disabled="!canEdit" @input="dirty=true"/><input v-model.number="band.q" type="range" min="0.2" max="10" step="0.05" aria-label="Q 值滑块" :disabled="!canEdit" @input="dirty=true"/></label></div>
            <p class="hint">{{band.type==='peak'?'Q 越小，调整越宽；Q 越大，越聚焦。':'Q ≈ 0.707 为平顺过渡；更高的 Q 会在转折处产生共振。'}}</p>
          </div>

        </template>
        <template v-else>
          <div class="setting"><div><strong>启用 USB 低音炮</strong><p>{{status.bassPresent?'检测到 USB 音频节点；请确认已连接低音炮和功放。':'未检测到 USB 音频节点。'}}播放中也可切换。</p></div><MdSwitch v-model="draft.bassEnabled" aria-label="启用 USB 低音炮" :disabled="!canEdit||liveBusy||(!draft.bassEnabled&&!status.bassPresent)" @update:model-value="toggleBass"/></div>
          <CrossoverControls v-if="independentCrossover" :satellite-highpass-hz="draft.satelliteHighpassHz??draft.crossoverHz" :bass-lowpass-hz="draft.bassLowpassHz??draft.crossoverHz" :disabled="!canEdit||!draft.bassEnabled" @update:satellite-highpass-hz="draft.satelliteHighpassHz=$event;dirty=true" @update:bass-lowpass-hz="draft.bassLowpassHz=$event;dirty=true"/>
          <label v-else class="range-setting"><span>分频点 · Linkwitz–Riley 24 dB/oct</span><output>{{draft.crossoverHz}} Hz</output><input v-model.number="draft.crossoverHz" type="range" min="40" max="300" step="5" :disabled="!canEdit||!draft.bassEnabled" @input="dirty=true"/></label>
          <div class="output-grid"><section v-for="(channel,i) in channels" :key="channel"><h4>{{channel}}</h4><label>增益 (dB)<input v-model.number="draft.outputGainDb[i]" type="number" min="-24" max="6" step="0.5" :disabled="!canEdit" @input="dirty=true"/></label><label>延迟 (ms)<input v-model.number="draft.delayMs[i]" type="number" min="0" max="100" step="0.1" :disabled="!canEdit" @input="dirty=true"/></label><MdSwitch :model-value="!!draft.invert[i]" label="反相" :disabled="!canEdit" @update:model-value="draft.invert[i]=$event;dirty=true"/></section></div>
        </template>
        <div class="master-section"><label class="range-setting"><span>主增益 · 留出提升余量</span><output>{{draft.masterDb}} dB</output><input v-model.number="draft.masterDb" type="range" min="-30" max="0" step="0.5" :disabled="!canEdit" @input="dirty=true"/></label><div class="headroom" :class="{warning:headroomLow}"><span>{{draft.bypass?'旁通保留主增益与峰值保护。':headroomInsufficient?'提升超过主增益可留出的余量，请降低频段增益。':`EQ 最大提升 ${boost.toFixed(1)} dB · 建议主增益 ≤ ${recommended} dB`}}</span><MdButton v-if="headroomLow&&!headroomInsufficient" variant="text" :disabled="!canEdit" @click="draft.masterDb=recommended;dirty=true">留足余量</MdButton></div></div>
        <div class="setting"><div><strong>旁通 DSP</strong><p>关闭 EQ、分频与声道校准；采样率、主增益和峰值保护不变。</p></div><MdSwitch v-model="draft.bypass" aria-label="旁通 DSP" :disabled="!canEdit" @update:model-value="dirty=true"/></div>
        <p v-if="!valid" class="service-error" role="alert">请填写有效参数：频率 20–18000 Hz，增益 −12–12 dB，Q 0.2–10。</p>
        <div class="save-row"><span class="hint" aria-live="polite">{{liveBusy?'正在实时更新…':status.settingsSaved===false?'已实时生效，尚未保存。':dirty?'有未保存的修改。':'设置已保存到设备。'}}</span><div class="buttons"><MdButton v-if="mode==='eq'" variant="text" :disabled="!canEdit||liveBusy" @click="resetEq">重置均衡器</MdButton><MdButton variant="text" :disabled="(!dirty&&status.settingsSaved!==false)||!canEdit||liveBusy" @click="undo">撤销修改</MdButton><MdButton :disabled="(!dirty&&status.settingsSaved!==false)||!canEdit||!valid||liveBusy" @click="apply">{{busy?'正在保存…':liveEnabled&&mode==='eq'?'保存设置':'应用并保存'}}</MdButton></div></div>
      </section>
      <section class="ui-panel control-card playback">
        <div class="section-head"><div><span class="eyebrow">COMMON AUDIO ENGINE</span><h3>{{status.running?sourceLabel:'等待音频输入'}}</h3></div><span class="mode-tag" :class="{ok:status.running}">{{status.stopping?'正在停止':status.running?'48 kHz · 处理中':'48 kHz · 就绪'}}</span></div>
        <p v-if="status.lastError" role="alert" class="service-error">{{status.lastError===-4?'普通播放已让给电话通话':`播放错误 ${status.lastError}：请检查音频设备、文件格式或设备占用。`}}</p>
        <dl class="telemetry"><div><dt>处理帧</dt><dd>{{status.processedFrames.toLocaleString()}}</dd></div><div><dt>输出峰值</dt><dd>{{status.outputPeak>0?(20*Math.log10(status.outputPeak)).toFixed(1):'−∞'}} <small>dBFS</small></dd></div><template v-if="draft.bassEnabled"><div><dt>USB 队列校正</dt><dd>{{status.usbClockPpm.toFixed(0)}} <small>ppm</small></dd></div><div><dt>USB 欠载</dt><dd>{{status.usbUnderruns}}</dd></div></template></dl>
        <details class="test-player"><summary>测试文件播放</summary><div class="play-row"><select v-model="track" aria-label="DSP 播放文件" :disabled="busy||status.running"><option value="" disabled>选择 48 kHz 立体声 WAV</option><option v-for="name in tracks" :key="name">{{name}}</option></select><MdButton variant="text" @click="library">刷新曲库</MdButton></div><p class="hint">普通音乐直接在音乐页播放，蓝牙与语音也会自动通过 DSP。这里仅用于测试标准 48 kHz 双声道 WAV。</p><div class="buttons"><MdButton v-if="status.running&&status.source==='test'" :disabled="busy" @click="action('dsp.stop')">停止测试</MdButton><MdButton v-else :disabled="status.running||!track||busy||dirty||!session.canControl||!!status.simulated" @click="action('dsp.play',{track})">播放测试文件</MdButton></div></details>
      </section>
    </template>
  </div>
</template>
